{
  "items": [
    {
      "title": "GERDA: German Election Database – Federal Elections (2013 and 2017)",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Comprehensive dataset containing German federal election results at the municipality, county, and constituency levels. Includes the 2013 and 2017 Bundestag elections, with information on party vote shares and voter turnout. Provides harmonized geographical boundaries for comparisons across elections. Data are available in CSV, Excel, and RDS formats."
    },
    {
      "title": "GERDA: German Election Database – State Elections (2010–2019)",
      "url_or_doi": "https://www.german-elections.com/",
      "justification": "Contains detailed results from German state parliamentary elections (Landtagswahlen) throughout the 2010s. Includes municipality-level party vote shares and election outcomes across Germany's 16 federal states. Particularly useful for investigating regional voting patterns, political polarization, and the emergence of Alternative for Germany (AfD)."
    },
    {
      "title": "GERDA: The German Election Database – Scientific Data Publication",
      "url_or_doi": "https://doi.org/10.1038/s41597-025-04811-5",
      "justification": "Peer-reviewed publication documenting the German Election Database, which provides harmonized election results covering federal, state, and municipal elections during the 2010s. Describes data collection, geographic standardization, validation procedures, and dataset coverage. Particularly valuable for researchers requiring transparent methodology and reproducible electoral data."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Federal Election Surveys 2013 and 2017",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Major German election research program providing individual-level survey datasets from the 2013 and 2017 federal elections. Includes voting behavior, political preferences, party identification, demographic characteristics, political attitudes, and campaign-related information. Supports analysis of voter behavior and electoral change during the 2010s."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Long-Term Panel 2009–2017",
      "url_or_doi": "https://www.gesis.org/en/gles/overview",
      "justification": "Longitudinal election survey data following respondents across multiple German federal elections, including 2013 and 2017. Enables researchers to investigate changes in voting intentions, party identification, political attitudes, and electoral participation over time. Particularly suitable for studying individual-level changes in German political behavior during the 2010s."
    },
    {
      "title": "GLES Candidate Study – German Federal Election 2013",
      "url_or_doi": "https://gles.eu/daten/kandidatenstudie-2013/",
      "justification": "Survey dataset examining candidates participating in Germany's 2013 federal election. Contains information on candidates' political backgrounds, campaign activities, attitudes, and political priorities. Useful for investigating candidate characteristics, party differences, and electoral competition during the 2013 Bundestag election."
    },
    {
      "title": "GLES Candidate Study – German Federal Election 2017",
      "url_or_doi": "https://gles.eu/daten/kandidatenstudie-2017/",
      "justification": "Dataset covering candidates in the 2017 German federal election, including their political characteristics, campaign experiences, and policy positions. Supports comparisons between political parties and candidates, as well as longitudinal research when combined with the 2013 candidate study."
    },
    {
      "title": "GLES – European Candidate Study 2014",
      "url_or_doi": "https://gles.eu/daten/europaeische-kandidatenstudie-2014/",
      "justification": "Survey data concerning German candidates participating in the 2014 European Parliament elections. Provides information on candidate backgrounds, political attitudes, electoral campaigns, and European integration. Relevant for research on Germany's participation in European elections during the 2010s."
    },
    {
      "title": "GESIS Research Data Center Elections – German State Election Surveys",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "Research data center providing access to German electoral survey datasets, including studies of state parliamentary elections conducted throughout the 2010s. Covers voter preferences, political attitudes, election participation, and demographic characteristics. Useful for comparing electoral behavior across Germany's federal states."
    },
    {
      "title": "Konrad Adenauer Foundation – German Election Results Since 1946",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Historical election statistics covering German federal, European Parliament, and state elections, including elections held between 2010 and 2019. Provides party vote shares, parliamentary seat distributions, and representative electoral statistics disaggregated by age and gender. Particularly useful for comparing electoral trends and demographic voting patterns."
    },
    {
      "title": "GERDA: German Municipal Election Results During the 2010s",
      "url_or_doi": "https://github.com/awiedem/german_election_data",
      "justification": "Open research repository containing German election datasets, including municipal council election results from the 2010s. Provides local-level political party vote shares, turnout information, and geographically harmonized datasets. Suitable for studying municipal political competition, local electoral variation, and relationships between local and national voting patterns."
    },
    {
      "title": "German Longitudinal Election Study – Election Campaign Panels and Rolling Cross-Sections",
      "url_or_doi": "https://erato.wzb.eu/en/research/completed-research-programs/democracy-and-democratization/downloads",
      "justification": "Research data collection providing access to GLES election campaign panels, rolling cross-sectional surveys, tracking surveys, and media content datasets associated with German federal elections in 2013 and 2017. Useful for analyzing campaign dynamics, changes in voter preferences, media influence, and political opinion formation during election periods."
    },
    {
      "title": "GESIS – German Longitudinal Election Study Candidate Campaign Surveys 2013 and 2017",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "GESIS documentation and access portal identifying the 2013 Candidate Campaign Survey (ZA5716) and the 2017 Candidate Campaign Survey (ZA6814). These datasets support comparative research on German parliamentary candidates, campaign strategies, political recruitment, and candidate-level electoral behavior across two federal elections in the 2010s."
    }
  ]
}
